add_action('init',function(){if(!function_exists('wc_get_product')||get_option('bhc_samsung_images_v352_done'))return;$items=[341=>['file'=>'samsung-ww80j3230kw-v352.png','prompt'=>'Samsung WW80J3230KW/SE WW80J 8kg white front-load washing machine with Diamond Drum and LED panel, exact model-specific transparent 4K ecommerce cutout'],342=>['file'=>'samsung-ww90j54e0bw-v352.png','prompt'=>'Samsung WW90J54E0BW/SE WW90J 9kg white front-load steam washing machine, exact model-specific transparent 4K ecommerce cutout'],359=>['file'=>'samsung-ua50cu7000uxly-v352.png','prompt'=>'Samsung UA50CU7000UXLY 50-inch Crystal UHD 4K CU7000 black television, exact model-specific transparent 4K ecommerce cutout'],362=>['file'=>'samsung-ua75cu7000uxly-v352.png','prompt'=>'Samsung UA75CU7000UXLY 75-inch Crystal UHD 4K CU7000 black television, exact model-specific transparent 4K ecommerce cutout']];$dir=plugin_dir_path(__FILE__).'bhc-image-references/';if(!is_dir($dir))wp_mkdir_p($dir);require_once ABSPATH.'wp-admin/includes/image.php';$ok=0;foreach($items as $id=>$row){$path=$dir.$row['file'];if(!file_exists($path))continue;$old=get_post_thumbnail_id($id);if($old)wp_delete_attachment($old,true);$u=wp_upload_bits($row['file'],null,file_get_contents($path));if(!empty($u['error']))continue;$type=wp_check_filetype($u['file'],null);$aid=wp_insert_attachment(['post_mime_type'=>$type['type'],'post_title'=>get_the_title($id).' تصویر اختصاصی','post_status'=>'inherit'],$u['file'],$id);wp_update_attachment_metadata($aid,wp_generate_attachment_metadata($aid,$u['file']));set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','generated_4k_transparent_verified');update_post_meta($id,'_bhc_image_prompt',$row['prompt'].'؛ PNG شفاف، بدون متن و واترمارک.');update_post_meta($id,'_bhc_image_checked_at','2026-11-20');$ok++;}update_option('bhc_samsung_images_v352_done',$ok===count($items)?1:0,false);});
